<?= $this->extend('layout') ?><?= $this->section('content') ?>
<section class="panel form-panel"><form method="post" enctype="multipart/form-data" action="<?= site_url($type.'/save') ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= esc($row['id']??'','attr') ?>">
<?php $fields=match($type){'products'=>['name'=>['Product name','text'],'price'=>['Price in PHP','number'],'stock_quantity'=>['Stock quantity','number']],'customers'=>['full_name'=>['Full name','text'],'email'=>['Email','email'],'phone'=>['Phone','tel']],'staff'=>['full_name'=>['Full name','text'],'username'=>['Username','text'],'password'=>['Password','password']]}; foreach($fields as $key=>[$label,$input]): ?>
<label><?= esc($label) ?><input type="<?= $input ?>" name="<?= $key ?>" value="<?= $key==='password'?'':esc($row[$key]??'','attr') ?>" <?= ($key==='phone'||($key==='password'&&!empty($row)))?'':'required' ?> <?= $key==='price'?'min="0" max="99999999.99" step="0.01"':($key==='stock_quantity'?'min="0" max="2147483647" step="1"':'') ?> <?= $key==='password'?'minlength="12" maxlength="72" autocomplete="new-password"':($key==='username'?'minlength="3" maxlength="50" pattern="[a-z0-9._-]+"':($key==='phone'?'maxlength="20"':'maxlength="100"')) ?>><?php if($key==='password'): ?><small>12–72 characters. <?= $row?'Leave empty to keep the current password.':'' ?></small><?php elseif($key==='username'): ?><small>Lowercase letters, numbers, periods, underscores and hyphens.</small><?php endif ?></label><?php endforeach ?>
<?php if($type!=='customers'): $field=$type==='staff'?'avatar':'image'; ?><label><?= $type==='staff'?'Avatar':'Product image' ?><input type="file" name="<?= $field ?>" accept="image/jpeg,image/png,image/webp"><small>JPEG, PNG or WebP. Maximum 2 MB and 16 megapixels. <?= $type==='staff'?'Avatars are cropped to 256 × 256 pixels.':'Product images are resized to fit 1000 × 1000 pixels.' ?></small></label><?php if(!empty($row[$field])): ?><img class="preview" src="<?= site_url('media/'.$row[$field]) ?>" alt="Current image"><?php endif; endif ?>
<div class="form-actions"><button>Save <?= $type==='staff'?'staff member':rtrim($type,'s') ?></button><a class="button secondary" href="<?= site_url($type) ?>">Cancel</a></div></form></section><?= $this->endSection() ?>
